let decorSelected=null;
function decorScale(d){return Number.isFinite(d.scale)?Math.max(.4,Math.min(2,d.scale)):1}
function orderedDecor(){return tank().decor.slice().sort((a,b)=>(Number.isFinite(a.layer)?a.layer:a.y)-(Number.isFinite(b.layer)?b.layer:b.y))}
function nextDecorLayer(){return Math.max(0,...tank().decor.map(d=>Number.isFinite(d.layer)?d.layer:d.y))+1}
function moveDecorLayer(d,action){const list=orderedDecor(),i=list.indexOf(d);if(i<0)return;list.splice(i,1);const j=action==='front'?list.length:action==='back'?0:action==='forward'?Math.min(i+1,list.length):Math.max(0,i-1);list.splice(j,0,d);list.forEach((item,index)=>item.layer=index);save();renderDecorEditor()}
function renderDecorEditor(){const panel=$('decorEditor');panel.hidden=!editing;if(!editing)return;const list=orderedDecor();let d=list.find(x=>x.uid===decorSelected);if(!d){d=list[list.length-1];decorSelected=d?.uid||null}panel.innerHTML='<strong>Editar decoraciones</strong><p>Arrastra una pieza en el acuario o elígela aquí, aunque esté detrás de otra.</p><label>Pieza<select id="decorChoice">'+list.map((x,i)=>'<option value="'+x.uid+'">'+deco(x.id).name+' · capa '+(i+1)+'</option>').join('')+'</select></label>'+(d?'<label>Tamaño <output id="decorSizeValue">'+Math.round(decorScale(d)*100)+'%</output><input id="decorSize" type="range" min="40" max="200" step="5" value="'+Math.round(decorScale(d)*100)+'"></label><div class="actions"><button id="decorMirror" aria-pressed="'+!!d.flip+'">↔ Reflejar</button><button id="decorReset">Tamaño original</button></div><div class="actions"><button id="decorBack">Al fondo</button><button id="decorBackward">Una capa atrás</button><button id="decorForward">Una capa delante</button><button id="decorFront">Al frente</button></div><div class="actions"><button id="decorStore">Guardar en almacén</button><button id="decorDone">Terminar</button></div>':'<p>Compra y coloca una decoración para editarla.</p><button id="decorDone">Terminar</button>');if(d){$('decorChoice').value=d.uid;$('decorChoice').onchange=()=>{decorSelected=$('decorChoice').value;renderDecorEditor()};$('decorSize').oninput=()=>{d.scale=Number($('decorSize').value)/100;$('decorSizeValue').textContent=Math.round(d.scale*100)+'%';save()};$('decorMirror').onclick=()=>{d.flip=!d.flip;save();renderDecorEditor()};$('decorReset').onclick=()=>{d.scale=1;save();renderDecorEditor()};for(const [id,action] of [['decorBack','back'],['decorBackward','backward'],['decorForward','forward'],['decorFront','front']])$(id).onclick=()=>moveDecorLayer(d,action);const i=list.indexOf(d);$('decorBack').disabled=$('decorBackward').disabled=i===0;$('decorFront').disabled=$('decorForward').disabled=i===list.length-1;$('decorStore').onclick=()=>{tank().decor=tank().decor.filter(x=>x.uid!==d.uid);state.inventory.push({uid:d.uid,id:d.id,scale:decorScale(d),flip:!!d.flip});decorSelected=null;save();render()}}$('decorDone').onclick=()=>{$('edit').onclick()}}


