function substrate(id){return SUBSTRATES.find(x=>x.id===id)||SUBSTRATES[0]}
function ownedSubstrates(){return Array.isArray(state.substrates)?state.substrates:['sand']}
function chooseSubstrate(id){const item=SUBSTRATES.find(x=>x.id===id);if(!item)return;if(!ownedSubstrates().includes(id)){if(!pay(item.price))return;state.substrates=[...ownedSubstrates(),id]}tank().substrate=id;save();render();toast(item.name+' aplicado a este acuario.')}
function renderSubstrateShop(){document.querySelectorAll('#shopTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('shopTitle').textContent='Un fondo a tu gusto';$('shopSubtitle').textContent='Compra una vez y úsalo en todos tus acuarios.';$('shop').replaceChildren();SUBSTRATES.forEach(item=>{const owned=ownedSubstrates().includes(item.id),active=(tank().substrate||'sand')===item.id;const card=document.createElement('div');card.className='card';card.innerHTML='<div class="art substrate-art" aria-hidden="true"></div><div><span class="rarity">'+(owned?'EN TU COLECCIÓN':'SUSTRATO')+'</span><h3>'+item.name+'</h3><p>'+(item.sand?'Grano fino y relieve suave':'Piedras redondeadas con luces y sombras')+'</p><button '+(active?'disabled':'')+'>'+(active?'✓ En este acuario':owned?'Usar en este acuario':'🪙 '+item.price+' · Comprar y usar')+'</button></div>';const preview=card.querySelector('.substrate-art');preview.style.background='linear-gradient(150deg,'+item.colors[1]+','+item.colors[0]+')';for(let i=0;i<24;i++){const pebble=document.createElement('i');pebble.style.cssText='left:'+((i*37)%90)+'%;top:'+((i*23)%85)+'%;background:'+item.colors[i%item.colors.length]+';width:'+(item.sand?3:9+i%5)+'px;height:'+(item.sand?2:6+i%4)+'px;transform:rotate('+(i*29)+'deg)';preview.append(pebble)}card.querySelector('button').onclick=()=>chooseSubstrate(item.id);$('shop').append(card)})}
const substrateCache=new Map();
function drawSubstrate(){const item=substrate(tank().substrate),key=item.id+'-'+W+'-'+H;let surface=substrateCache.get(key);if(!surface){substrateCache.clear();surface=document.createElement('canvas');surface.width=W;surface.height=H;const c=surface.getContext('2d');let seed=8721;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};c.beginPath();c.moveTo(0,H*.89);c.quadraticCurveTo(W*.5,H*.84,W,H*.9);c.lineTo(W,H);c.lineTo(0,H);c.closePath();c.save();c.clip();const base=c.createLinearGradient(0,H*.86,0,H);base.addColorStop(0,item.colors[3]);base.addColorStop(.25,item.colors[0]);base.addColorStop(1,item.colors[1]);c.fillStyle=base;c.fillRect(0,H*.85,W,H*.15);if(item.sand){for(let i=0;i<9;i++){c.strokeStyle=i%2?'#fff6df20':'#71603d18';c.lineWidth=2+i%3;c.beginPath();for(let x=0;x<=W;x+=8){const y=H*(.88+i*.014)+Math.sin(x/90+i)*3;x?c.lineTo(x,y):c.moveTo(x,y)}c.stroke()}for(let i=0;i<W*H*.025;i++){const x=rand()*W,y=H*(.85+rand()*.15),r=.35+rand()*.75;c.fillStyle=item.colors[Math.floor(rand()*item.colors.length)];c.globalAlpha=.3+rand()*.5;c.fillRect(x,y,r*1.5,r)}c.globalAlpha=1}else{for(let row=0;row<16;row++){const depth=row/15,y=H*(.86+.15*depth),size=2+depth*3;for(let x=-10;x<W+10;x+=size*1.9){const px=x+(rand()-.5)*size,py=y+(rand()-.5)*size,rx=size*(.8+rand()*.5),ry=size*(.55+rand()*.3);c.fillStyle='#233d4440';c.beginPath();c.ellipse(px+.8,py+1.2,rx,ry,0,0,7);c.fill();const shine=c.createRadialGradient(px-rx*.3,py-ry*.4,.1,px,py,rx);shine.addColorStop(0,item.colors[1]);shine.addColorStop(.4,item.colors[Math.floor(rand()*item.colors.length)]);shine.addColorStop(1,item.colors[3]);c.fillStyle=shine;c.beginPath();c.ellipse(px,py,rx,ry,rand()*.5,0,7);c.fill();c.fillStyle='#ffffff35';c.beginPath();c.ellipse(px-rx*.2,py-ry*.35,rx*.35,ry*.15,0,0,7);c.fill()}}}c.restore();substrateCache.set(key,surface)}ctx.drawImage(surface,0,0)}


