const HALLOWEEN_MISSIONS=[{key:'fed',goal:1,title:'Un bocado de bienvenida',text:'Alimenta a tus peces 1 vez.'},{key:'cleaned',goal:1,title:'Agua sin fantasmas',text:'Limpia un acuario 1 vez.'},{key:'collected',goal:2,title:'Botín de medianoche',text:'Recolecta monedas de tus peces 2 veces.'},{key:'foodBought',goal:1,title:'La despensa de la bruja',text:'Compra alimento 1 vez.'},{key:'decorated',goal:3,title:'Un refugio misterioso',text:'Coloca decoraciones 3 veces.'},{key:'trained',goal:1,title:'Truco o burbuja',text:'Completa 1 entrenamiento.'},{key:'bought',goal:2,title:'Invitados al arrecife',text:'Compra 2 peces.'},{key:'dailyClaims',goal:2,title:'Dos noches de tesoro',text:'Abre el cofre diario en 2 días distintos.'},{key:'bred',goal:1,title:'Una nueva vida',text:'Cría 1 pez.'},{key:'fed',goal:15,title:'Banquete de Halloween',text:'Alimenta a tus peces 15 veces.'}];
function halloweenState(){return state.events?.halloween||null}
function startHalloween(){if(halloweenState())return;state.events=state.events||{};state.events.halloween={baseline:{...state.stats},claimed:[],fishClaimed:false,fishPlaced:false};save();renderEvents();toast('🎃 ¡Comienza Halloween! Tus nuevas acciones cuentan para las misiones.')}
function eventProgress(i){const e=halloweenState(),m=HALLOWEEN_MISSIONS[i];return e&&m?Math.max(0,(state.stats[m.key]||0)-(e.baseline[m.key]||0)):0}
function claimHalloween(i){const e=halloweenState(),m=HALLOWEEN_MISSIONS[i];if(!e||!m||e.claimed.includes(i)||eventProgress(i)<m.goal)return false;e.claimed.push(i);state.inventory.push({uid:uid(),id:'hw'+(i+1)});xp(20);save();render();toast('🎃 '+deco('hw'+(i+1)).name+' desbloqueado. Está en el Almacén.');return true}
function claimHalloweenFish(){const e=halloweenState();if(!e||e.claimed.length!==10||e.fishClaimed)return false;e.fishClaimed=true;save();renderEvents();toast('🐟 Colmillo de Plata desbloqueado. Elige un acuario con espacio para recibirlo.');return true}
function placeHalloweenFish(){const e=halloweenState();if(!e?.fishClaimed||e.fishPlaced)return false;if(tank().fish.length>=capacity()){toast('Este acuario está lleno. Amplíalo o elige otro para recibir tu pez.');return false}tank().fish.push(fish('fang','Colmillo de Plata'));e.fishPlaced=true;save();render();toast('¡Colmillo de Plata llegó a tu acuario!');return true}
function renderEvents(){const host=$('eventBody');if(!host)return;const e=halloweenState();$('eventCount').textContent=e?e.claimed.length+'/10 recompensas':'10 decoraciones + 1 pez';host.innerHTML='<div class="event-banner"><span class="event-badge">ACTIVO · EDICIÓN HALLOWEEN</span><h2>El arrecife de medianoche</h2><p>Misiones de cuidado, tesoros y nuevos amigos. Tus recompensas se quedan en tu colección.</p><p class="event-note">Sin fecha de cierre por ahora. El progreso comienza al participar y cuenta en todos tus acuarios.</p></div>';if(!e){host.insertAdjacentHTML('beforeend','<button id="startHalloween">🎃 Participar en Halloween</button>');$('startHalloween').onclick=startHalloween;return}const grid=document.createElement('div');grid.className='event-missions';HALLOWEEN_MISSIONS.forEach((m,i)=>{const claimed=e.claimed.includes(i),n=Math.min(m.goal,eventProgress(i)),reward=deco('hw'+(i+1));const card=document.createElement('article');card.className='event-mission'+(claimed?' completed':'');card.innerHTML='<img src="'+reward.src+'" alt="'+reward.name+'"><div><span class="event-badge">RECOMPENSA '+(i+1)+'</span><h3>'+m.title+'</h3><p>'+m.text+'</p><strong>'+reward.name+'</strong><label class="event-progress">Progreso '+n+'/'+m.goal+'<progress max="'+m.goal+'" value="'+n+'"></progress></label><button '+(claimed||n<m.goal?'disabled':'')+'>'+(claimed?'✓ En tu colección':n>=m.goal?'Reclamar decoración':'Misión en curso')+'</button></div>';card.querySelector('button').onclick=()=>claimHalloween(i);grid.append(card)});host.append(grid);const final=document.createElement('article');final.className='event-fish';final.innerHTML='<img src="assets/halloween-fish.png" alt="Colmillo de Plata"><div><span class="event-badge">PEZ EXCLUSIVO</span><h3>Colmillo de Plata</h3><p>Reclama las 10 decoraciones para desbloquear este pez plateado. Nada con fuerza, mueve sus aletas y busca el alimento. Convive con tus otros peces.</p><strong>'+e.claimed.length+'/10 recompensas reclamadas</strong><div><button id="claimEventFish" '+(e.fishClaimed||e.claimed.length<10?'disabled':'')+'>'+(e.fishClaimed?'✓ Pez desbloqueado':'Desbloquear pez')+'</button>'+(e.fishClaimed&&!e.fishPlaced?'<button id="placeEventFish">Recibir en este acuario</button>':'')+'</div>'+(e.fishPlaced?'<p>Tu pez ya está en la partida. Puedes renombrarlo y entrenarlo.</p>':'')+'</div>';host.append(final);$('claimEventFish').onclick=claimHalloweenFish;if($('placeEventFish'))$('placeEventFish').onclick=placeHalloweenFish;}
function drawHalloweenFX(d,time,r){const id=d.id;if(!id.startsWith('hw'))return;ctx.save();ctx.translate(d.x*W,d.y*H);ctx.scale(d.flip?-1:1,1);if(id==='hw4'){ctx.fillStyle='rgba(166,255,64,'+(.2+Math.sin(time*3)*.1)+')';ctx.beginPath();ctx.ellipse(0,-r.h*.67,r.w*.22,r.h*.035,0,0,7);ctx.fill();for(let i=0;i<9;i++){const lift=(time*25+i*13)%110;ctx.strokeStyle='rgba(185,255,109,'+(1-lift/120)+')';ctx.lineWidth=1.4;ctx.beginPath();ctx.arc(Math.sin(time+i)*r.w*.09,-r.h*.65-lift*r.h/175,2+i%4,0,7);ctx.stroke()}}if(['hw1','hw2','hw3','hw7','hw9'].includes(id)){const positions=id==='hw1'?[[0,-.53]]:id==='hw9'?[[-.31,-.67],[.32,-.42]]:[[-.28,-.24],[.28,-.28]];for(const [x,y] of positions){const glow=ctx.createRadialGradient(x*r.w,y*r.h,0,x*r.w,y*r.h,r.w*.11);glow.addColorStop(0,'rgba(255,169,51,'+(.25+Math.sin(time*3+d.x)*.12)+')');glow.addColorStop(1,'rgba(255,130,30,0)');ctx.fillStyle=glow;ctx.fillRect((x-.12)*r.w,(y-.12)*r.h,r.w*.24,r.h*.24)}}if(['hw5','hw6','hw7','hw10'].includes(id)){for(let i=0;i<4;i++){const cycle=(time*.17+i*.25)%1;ctx.globalAlpha=Math.sin(cycle*Math.PI)*.65;ctx.fillStyle='#c8b5ff';ctx.beginPath();ctx.ellipse(Math.sin(time+i*2)*r.w*.3,-r.h*(.15+cycle*.85),r.w*.018,r.h*.05,Math.sin(time+i)*.4,0,7);ctx.fill()}}if(id==='hw8'){for(let i=0;i<2;i++){const x=Math.sin(time*.7+i*3)*r.w*.5,y=-r.h*(.65+Math.cos(time+i)*.12),wing=3+Math.sin(time*12)*3;ctx.fillStyle='#402951';ctx.beginPath();ctx.moveTo(x,y+2);ctx.lineTo(x-8,y-wing);ctx.lineTo(x-4,y+2);ctx.lineTo(x,y);ctx.lineTo(x+4,y+2);ctx.lineTo(x+8,y-wing);ctx.closePath();ctx.fill()}}ctx.restore()}

const KEY='acuario-feliz-v1', $=id=>document.getElementById(id), uid=()=>crypto.randomUUID(), species=id=>SPECIES.find(s=>s.id===id), deco=id=>DECOR.find(d=>d.id===id);let tab='fish',placing=null,editing=false,selected=null,trainingTimer=null,particles=[],feeding=false,bottle={x:.5,y:.1,visible:false,pour:0},lastFrame=performance.now();
