function initial(){return{version:1,coins:650,xp:0,food:50,active:0,tanks:[{name:'Mi primer arrecife',clean:92,size:0,bank:0,theme:0,fish:[fish('sun','Clementina',true),fish('blue','Nube',true),fish('sun','Mango')],decor:[{uid:uid(),id:'plant',x:.12,y:.88},{uid:uid(),id:'coral',x:.8,y:.9},{uid:uid(),id:'rock',x:.58,y:.92}]}],inventory:[],stats:{fed:0,cleaned:0,bought:0,bred:0,trained:0,decorated:0,collected:0,foodBought:0,dailyClaims:0,sold:0,expanded:0},claimed:[],daily:'',last:Date.now()}}
let state;try{state=normalizeSave(JSON.parse(localStorage.getItem(KEY)));if(!valid(state))state=initial()}catch{state=initial()}
function normalizeSave(s){if(!s||!Array.isArray(s.tanks)||!Array.isArray(s.inventory))return s;if(s.events?.halloween){const e=s.events.halloween;if(!e.baseline||typeof e.baseline!=='object'||!Array.isArray(e.claimed))delete s.events.halloween;else{e.claimed=[...new Set(e.claimed.filter(i=>Number.isInteger(i)&&i>=0&&i<10))];e.fishClaimed=!!e.fishClaimed;e.fishPlaced=!!e.fishPlaced}}s.substrates=Array.isArray(s.substrates)?[...new Set(['sand',...s.substrates.filter(id=>SUBSTRATES.some(x=>x.id===id))])]:['sand'];for(const t of s.tanks){if(!s.substrates.includes(t.substrate))t.substrate='sand'}const remap={chest:'ship',purple:'coral',grass:'plant',anemone:'coral',star:'shell',mushroom:'coral',anchor:'ship',pebbles:'rock',fan:'coral',tube:'coral',lily:'shell',crystal:'arch'};for(const t of s.tanks){if(Array.isArray(t.decor))for(const d of t.decor)d.id=remap[d.id]||d.id;}for(const d of s.inventory)d.id=remap[d.id]||d.id;if(s.stats){for(const key of ['foodBought','dailyClaims','sold','expanded'])if(!Number.isFinite(s.stats[key]))s.stats[key]=0;}return s;}
function valid(s){return s&&s.version===1&&Number.isFinite(s.coins)&&s.coins>=0&&Number.isFinite(s.xp)&&Number.isFinite(s.food)&&Array.isArray(s.tanks)&&s.tanks.length>0&&s.tanks.length<=5&&Number.isInteger(s.active)&&s.active>=0&&s.active<s.tanks.length&&Array.isArray(s.inventory)&&s.inventory.every(i=>deco(i.id))&&Array.isArray(s.claimed)&&s.stats&&Number.isFinite(s.last)&&s.tanks.every(t=>typeof t.name==='string'&&Number.isFinite(t.clean)&&Number.isFinite(t.bank)&&Number.isInteger(t.size)&&t.size>=0&&t.size<=4&&Array.isArray(t.decor)&&t.decor.every(d=>deco(d.id)&&Number.isFinite(d.x)&&Number.isFinite(d.y))&&Array.isArray(t.fish)&&t.fish.every(f=>species(f.species)&&typeof f.name==='string'&&['age','hunger','x','y','cooldown','trained'].every(k=>Number.isFinite(f[k]))))}
const tank=()=>state.tanks[state.active],level=()=>1+Math.floor(Math.sqrt(state.xp/55)),capacity=()=>8+tank().size*4;
function simulate(seconds){if(typeof gamePaused!=='undefined'&&gamePaused)return;seconds=Math.max(0,Math.min(seconds,28800));state.tanks.forEach(t=>{const before=t.clean;t.clean=Math.max(15,t.clean-seconds*.018);t.fish.forEach(f=>{const s=species(f.species),productive=Math.max(0,Math.min(seconds,(f.hunger-20)/.055,(before-35)/.018));if(productive>0){f.age=Math.min(s.grow,f.age+productive);t.bank=Math.min(5000,t.bank+productive*s.rate/25*(1+f.trained*.12))}f.hunger=Math.max(0,f.hunger-seconds*.055);f.cooldown=Math.max(0,f.cooldown-seconds)})})}
let gamePaused=false,storageKey=KEY;
simulate((Date.now()-state.last)/1000);
function save(){if(gamePaused)return;state.last=Date.now();try{localStorage.setItem(storageKey,JSON.stringify(state));if(storageKey===KEY)$('saveStatus').textContent='✓ Progreso guardado en este navegador';window.dispatchEvent(new Event('aquarium-save'));}catch{$('saveStatus').textContent='Sin espacio: exporta tu partida desde ☰'}}
window.aquariumGame={snapshot:()=>JSON.parse(JSON.stringify(state)),fresh:()=>normalizeSave(initial()),validate:s=>{try{return !!valid(normalizeSave(JSON.parse(JSON.stringify(s))))}catch{return false}},storage:k=>{storageKey=k},pause:on=>{gamePaused=on;if(on){setFeeding(false);if(trainingTimer){clearInterval(trainingTimer);trainingTimer=null}$('dialog').close()}},replace:incoming=>{incoming=normalizeSave(JSON.parse(JSON.stringify(incoming)));if(!valid(incoming))throw Error('invalid_save');state=incoming;const paused=gamePaused;gamePaused=false;simulate((Date.now()-state.last)/1000);gamePaused=paused;particles=[];placing=null;editing=false;decorSelected=null;$('placement').style.display='none';$('edit').style.background='';render()},save};
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),3300)}
function xp(n){const old=level();state.xp+=n;if(level()>old)toast('✦ ¡Nivel '+level()+'! Nuevos amigos te esperan.')}function pay(n){if(state.coins<n){toast('Te faltan monedas. Recolecta las de tus peces.');return false}state.coins-=n;return true}
function fishSVG(s){return '<img class="fish-sprite" src="'+FISH_ASSETS[s.id].src+'" alt="'+s.name+'">'}
function fishImage(s){const key='sprite-'+s.id;if(!artCache.has(key)){const im=new Image();im.src=FISH_ASSETS[s.id].src;artCache.set(key,im)}return artCache.get(key)}
function drawSwimmingFish(im,size,time,index,chasing){if(!im.complete||!im.naturalWidth)return;const iw=im.naturalWidth,ih=im.naturalHeight,h=size*ih/iw,beat=time*(chasing?10:6)+index*1.7;const slices=40;for(let n=0;n<slices;n++){const u=n/slices,sw=iw/slices,tail=Math.pow(1-u,2),offset=Math.sin(beat+u*3.5)*size*.038*tail;ctx.drawImage(im,n*sw,0,sw,ih,-size/2+n*size/slices,-h/2+offset,size/slices+.35,h*(1+Math.sin(beat)*tail*.018));}}
function decorSVG(d){return '<img class="decor-sprite" src="'+d.src+'" alt="'+d.name+'">'}
function decorImage(d){const key='decor-'+d.id;if(!artCache.has(key)){const im=new Image();im.src=d.src;artCache.set(key,im)}return artCache.get(key)}
const artCache=new Map();function art(key,svg){if(!artCache.has(key)){const i=new Image();i.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);artCache.set(key,i)}return artCache.get(key)}
function render(){const t=tank();$('coins').textContent=Math.floor(state.coins).toLocaleString('es-MX');$('level').textContent=level();$('clean').textContent=Math.round(t.clean);$('capacity').textContent=t.fish.length+' / '+capacity();$('food').textContent=state.food+' porciones';$('income').textContent=Math.floor(t.bank)+' disponibles';$('upgradePrice').textContent=t.size>=4?'Tamaño máximo':(300*(t.size+1))+' monedas';$('tankLabel').textContent=t.name.toUpperCase();$('tankTabs').replaceChildren();state.tanks.forEach((t,i)=>{const b=document.createElement('button');b.textContent=t.name;b.className=i===state.active?'active':'';b.onclick=()=>{setFeeding(false);particles=[];state.active=i;placing=null;editing=false;$('placement').style.display='none';render();save()};$('tankTabs').append(b)});$('daily').textContent=dailyReady()?'🗝 Tesoro disponible':'✓ Tesoro recogido';$('treasure').setAttribute('aria-label',dailyReady()?'Abrir cofre: 200 monedas y 25 comidas gratis':'Cofre diario recogido; vuelve mañana');$('treasure').classList.toggle('ready',dailyReady());$('treasure').classList.toggle('opened',!dailyReady());renderQuest();renderShop();renderDecorEditor();renderEvents()}
function renderShop(){if(tab==='substrate'){renderSubstrateShop();return;}if(tab==='food'){renderFoodShop();return;}document.querySelectorAll('#shopTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('shopTitle').textContent={fish:'Pequeños nuevos amigos',decor:'Un hogar con personalidad',inventory:'Tu almacén'}[tab];$('shopSubtitle').textContent={fish:'Cría, cuida y descubre las 10 especies.',decor:'Compra y coloca cada pieza en la arena.',inventory:'Decoraciones guardadas, listas para usar.'}[tab];$('shop').replaceChildren();const items=tab==='fish'?SPECIES.filter(x=>!x.event):tab==='decor'?DECOR.filter(x=>!x.event):state.inventory.map(i=>({...deco(i.id),inventoryUid:i.uid}));if(tab==='inventory'&&!items.length){const p=document.createElement('p');p.className='empty';p.textContent='Tu almacén está vacío. Compra decoraciones o guarda las que tienes en el acuario.';$('shop').append(p)}items.forEach(s=>{const locked=tab==='fish'&&level()<s.level;const card=document.createElement('div');card.className='card';card.innerHTML=`<div class="art">${tab==='fish'?fishSVG(s):decorSVG(s)}</div><div><span class="rarity">${tab==='fish'?s.rarity:tab==='inventory'?'EN EL ALMACÉN':'DECORACIÓN'}</span><h3>${s.name}</h3><p>${tab==='fish'?s.rate+' monedas / 25 s · '+Math.ceil(s.grow/60)+' min':tab==='inventory'?'Listo para colocar':'Diseño original'}</p><button ${locked?'disabled':''}>${locked?'🔒 Nivel '+s.level:tab==='inventory'?'Colocar →':'🪙 '+s.price+' · Comprar'}</button></div>`;card.querySelector('button').onclick=()=>{if(tab==='fish'){if(tank().fish.length>=capacity())return toast('Tu acuario está lleno. Amplíalo o crea otro.');if(pay(s.price)){tank().fish.push(fish(s.id));state.stats.bought++;xp(15);toast(s.name+' se une a tu acuario');save();render()}}else if(tab==='decor'){if(pay(s.price)){const i={uid:uid(),id:s.id};state.inventory.push(i);startPlace(i);save();renderShop();$('coins').textContent=state.coins}}else startPlace({uid:s.inventoryUid,id:s.id})};$('shop').append(card)})}
function startPlace(item){decorSelected=null;setFeeding(false);placing=item;editing=false;$('placement').style.display='block';renderDecorEditor();toast('Haz clic en la parte inferior del acuario para colocarla.')}
const QUESTS=[{title:'La primera comida',text:'Alimenta a tus peces una vez.',key:'fed',goal:1,reward:100},{title:'Un hogar impecable',text:'Limpia tu acuario una vez.',key:'cleaned',goal:1,reward:120},{title:'Amigos nuevos',text:'Compra dos peces en la tienda.',key:'bought',goal:2,reward:220},{title:'Tu toque personal',text:'Coloca dos decoraciones.',key:'decorated',goal:2,reward:220},{title:'La familia crece',text:'Cría una pareja de peces adultos.',key:'bred',goal:1,reward:300},{title:'Un pez con talento',text:'Completa un entrenamiento.',key:'trained',goal:1,reward:250},{title:'Un océano de posibilidades',text:'Recolecta monedas cinco veces.',key:'collected',goal:5,reward:400}];
QUESTS.push({title:'Despensa preparada',text:'Compra alimento una vez.',key:'foodBought',goal:1,reward:80},{title:'Guardián del agua',text:'Limpia tus acuarios 10 veces.',key:'cleaned',goal:10,reward:250},{title:'Banquete marino',text:'Alimenta a tus peces 20 veces.',key:'fed',goal:20,reward:350},{title:'Decorador del océano',text:'Coloca 10 decoraciones.',key:'decorated',goal:10,reward:400},{title:'Cazador de tesoros',text:'Abre el cofre en 3 días distintos.',key:'dailyClaims',goal:3,reward:450},{title:'Una gran familia',text:'Cría 5 peces.',key:'bred',goal:5,reward:500},{title:'Escuela del arrecife',text:'Completa 10 entrenamientos.',key:'trained',goal:10,reward:500},{title:'Nuevos horizontes',text:'Amplía un acuario.',key:'expanded',goal:1,reward:200},{title:'Coleccionista',text:'Compra 10 peces.',key:'bought',goal:10,reward:600},{title:'Hogares nuevos',text:'Vende 3 peces.',key:'sold',goal:3,reward:300},{title:'El gran tesoro',text:'Recolecta monedas 25 veces.',key:'collected',goal:25,reward:650},{title:'Despensa del capitán',text:'Compra alimento 5 veces.',key:'foodBought',goal:5,reward:350});
function questValue(q){return state.stats[q.key]||0}
function renderQuest(){renderEvents();const i=QUESTS.findIndex((q,j)=>!state.claimed.includes(j));if(i<0){$('questTitle').textContent='¡Un acuario extraordinario!';$('questText').textContent='Todos los logros completados. Sigue coleccionando.';$('questClaim').style.display='none';return}const q=QUESTS[i],n=questValue(q);$('questTitle').textContent=q.title;$('questText').textContent=q.text+' '+Math.min(n,q.goal)+'/'+q.goal+' · +'+q.reward+' 🪙';$('questClaim').style.display='inline-block';$('questClaim').disabled=n<q.goal;$('questClaim').onclick=()=>{if(questValue(q)<q.goal||state.claimed.includes(i))return;state.claimed.push(i);state.coins+=q.reward;xp(35);save();render();toast('¡Logro completado! +'+q.reward+' monedas')}}
document.querySelectorAll('#shopTabs button').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;renderShop()});$('cancelPlace').onclick=()=>{placing=null;$('placement').style.display='none'};
function setFeeding(on){feeding=on;bottle.visible=false;$('tank').classList.toggle('feeding',on);$('feed').setAttribute('aria-pressed',String(on));$('feed').style.background=on?'#e0edcf':'';$('tip').textContent=on?'Mueve la botellita y haz clic dentro del agua para soltar comida. Pulsa Alimentar o Escape para terminar.':'Selecciona un pez para conocerlo, ponerle nombre o entrenarlo.';}
$('feed').onclick=()=>{if(!feeding){placing=null;editing=false;$('placement').style.display='none';$('edit').style.background='';}setFeeding(!feeding);renderDecorEditor();if(feeding)toast('Botellita lista: haz clic donde quieras echar comida.');};
function dropFood(q){if(state.food<1)return toast('La botellita está vacía. Compra alimento en la pestaña Alimento.');if(!tank().fish.length)return toast('Primero añade peces a este acuario.');if(tank().fish.every(f=>f.hunger>=98))return toast('Todos tus peces están satisfechos.');if(particles.filter(p=>p.type==='food'&&p.tank===state.active&&p.life>0).length>=40)return toast('Espera a que coman antes de echar más.');state.food--;bottle.pour=.5;const batch=uid();for(let i=0;i<5;i++)particles.push({x:Math.max(.03,Math.min(.97,q.x+(Math.random()-.5)*.04)),y:Math.max(.04,Math.min(.85,q.y))+i*.008,life:18,type:'food',tank:state.active,batch,counted:false});save();$('food').textContent=state.food+' porciones';}
function updateFeeding(dt){particles.forEach(p=>{p.life-=dt;if(p.type==='food')p.y=Math.min(.9,p.y+dt*.023)});const crumbs=particles.filter(p=>p.type==='food'&&p.tank===state.active&&p.life>0),claimed=new Set();tank().fish.forEach((f,i)=>{if(f.hunger>=98)return;let target=null,best=Infinity;for(const p of crumbs){if(claimed.has(p)||p.life<=0)continue;const d=Math.hypot((p.x-f.x)*1.58,p.y-f.y);if(d<best){best=d;target=p}}if(!target)return;claimed.add(target);const dx=target.x-f.x,dy=target.y-f.y,d=Math.hypot(dx,dy),step=Math.min(d,dt*(.19+(i%3)*.015));if(d>0){f.x+=dx/d*step;f.y+=dy/d*step;}if(Math.abs(dx)>.002)f.dir=dx>0?1:-1;f.chasing=true;if(d<.03){target.life=0;f.hunger=Math.min(100,f.hunger+22);f.age=Math.min(species(f.species).grow,f.age+2);f.bite=.5;if(!target.counted){particles.filter(p=>p.batch===target.batch).forEach(p=>p.counted=true);state.stats.fed++;xp(8);renderQuest();}particles.push({x:f.x,y:f.y,life:.6,type:'spark',tank:state.active});save();}});particles=particles.filter(p=>p.life>0);}
document.addEventListener('keydown',e=>{if(e.key==='Escape')setFeeding(false)});
$('scrub').onclick=()=>{if(tank().clean>=99)return toast('El agua ya está cristalina.');tank().clean=100;state.stats.cleaned++;xp(12);toast('🫧 Agua limpia y peces contentos.');save();render()};
$('collect').onclick=()=>{const n=Math.floor(tank().bank);if(n<1)return toast('Tus peces generan monedas cuando están alimentados y el agua está limpia.');tank().bank-=n;state.coins+=n;state.stats.collected++;xp(5);toast('+'+n+' monedas para tu colección');save();render()};
$('edit').onclick=()=>{setFeeding(false);editing=!editing;placing=null;$('placement').style.display='none';toast(editing?'Arrastra las decoraciones. Selecciona una para ajustar tamaño, reflejo y capas.':'Decoración terminada.');$('edit').style.background=editing?'#e0edcf':'';renderDecorEditor()};
$('upgrade').onclick=()=>{const t=tank();if(t.size>=4)return toast('Tu acuario tiene el tamaño máximo.');if(pay(300*(t.size+1))){t.size++;state.stats.expanded=(state.stats.expanded||0)+1;xp(35);toast('Ahora caben '+capacity()+' peces.');save();render()}};
$('newTank').onclick=()=>{if(state.tanks.length>=5)return toast('Ya tienes los cinco acuarios.');if(pay(800)){state.tanks.push({name:'Arrecife '+(state.tanks.length+1),clean:100,size:0,bank:0,theme:state.tanks.length%3,fish:[],decor:[]});state.active=state.tanks.length-1;xp(60);save();render()}};
function dayKey(){return new Date().toLocaleDateString('en-CA',{timeZone:'America/Mexico_City'})}
function dailyReady(){return state.daily!==dayKey()}
function claimTreasure(){if(!dailyReady())return toast('Ya abriste el cofre de hoy. Vuelve mañana.');state.daily=dayKey();state.coins+=200;state.food+=25;state.stats.dailyClaims=(state.stats.dailyClaims||0)+1;xp(10);$('treasure').classList.remove('ready');$('treasure').classList.add('opened');toast('🗝 ¡Tesoro encontrado! +200 monedas y 25 comidas');save();render();}
$('treasure').onclick=claimTreasure;$('daily').onclick=()=>{toast(dailyReady()?'Haz clic en el cofre dorado dentro del acuario.':'Ya recogiste el tesoro de hoy.');$('treasure').focus();};
const FOOD_PACKS=[{amount:25,price:25},{amount:50,price:40},{amount:150,price:100}];
function buyFoodPack(pack){if(!FOOD_PACKS.includes(pack)||!pay(pack.price))return false;state.food+=pack.amount;state.stats.foodBought=(state.stats.foodBought||0)+1;save();render();toast('🍼 +'+pack.amount+' porciones de alimento');return true;}
function renderFoodShop(){document.querySelectorAll('#shopTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('shopTitle').textContent='La despensa de tus peces';$('shopSubtitle').textContent='Tienes '+state.food+' porciones. Cada clic usa una.';$('shop').replaceChildren();FOOD_PACKS.forEach((pack,i)=>{const card=document.createElement('div');card.className='card';card.innerHTML='<div class="art food-art">🍼</div><div><span class="rarity">'+['BOLSITA','BOTELLITA','RESERVA'][i]+'</span><h3>'+pack.amount+' porciones</h3><p>Para alimentar con el mouse</p><button>🪙 '+pack.price+' · Comprar alimento</button></div>';card.querySelector('button').onclick=()=>buyFoodPack(pack);$('shop').append(card)})}
$('foodShortcut').onclick=()=>{tab='food';renderShop();$('shopTabs').scrollIntoView({behavior:'smooth',block:'nearest'})};
$('achievements').onclick=()=>{show('<h2>Logros del arrecife</h2><p>'+state.claimed.length+' de '+QUESTS.length+' recompensas recogidas</p><div id="achievementList"></div>');QUESTS.forEach((q,i)=>{const row=document.createElement('div');row.className='achievement';const done=state.claimed.includes(i),ready=questValue(q)>=q.goal;row.innerHTML='<h3>'+q.title+'</h3><p>'+q.text+' '+Math.min(questValue(q),q.goal)+'/'+q.goal+'</p><button '+(done||!ready?'disabled':'')+'>'+(done?'✓ Recogido':q.reward+' 🪙 · Reclamar')+'</button>';row.querySelector('button').onclick=()=>{if(state.claimed.includes(i)||questValue(q)<q.goal)return;state.claimed.push(i);state.coins+=q.reward;xp(35);save();render();row.querySelector('button').disabled=true;row.querySelector('button').textContent='✓ Recogido';toast('¡Logro completado! +'+q.reward+' monedas')};$('achievementList').append(row)})};
function show(html){$('dialogBody').innerHTML=html;$('dialog').showModal()}$('closeDialog').onclick=()=>{$('dialog').close()};$('dialog').addEventListener('close',()=>{if(trainingTimer){clearInterval(trainingTimer);trainingTimer=null}});
function fishInfo(f){selected=f.id;const s=species(f.species),adult=f.age>=s.grow;show(`<div class="portrait">${fishSVG(s)}</div><h2 id="fishName"></h2><p>${s.name} · ${adult?'Adulto':'En crecimiento'} · ${f.trained} entrenamientos</p><label>Nombre<input id="rename" maxlength="25"></label><p>Alimentación ${Math.round(f.hunger)}%</p><progress max="100" value="${f.hunger}"></progress><p>Crecimiento ${Math.round(f.age/s.grow*100)}%</p><progress max="${s.grow}" value="${f.age}"></progress><div class="actions"><button id="breed">💕 Criar · ${Math.floor(s.price*.4)} 🪙</button><button id="train">✦ Entrenar</button><button id="sell">Vender · ${sellValue(f)} 🪙</button></div><p>Cría con otro adulto de la misma especie, alimentado y con agua limpia. Espera 3 min entre crías.</p>`);$('fishName').textContent=f.name;$('rename').value=f.name;$('rename').onchange=()=>{f.name=$('rename').value.trim()||s.name;$('fishName').textContent=f.name;save()};if(s.event){$('breed').disabled=true;$('sell').disabled=true;$('breed').title=$('sell').title='Pez único del evento: se conserva en tu colección.'} $('breed').onclick=()=>breed(f);$('train').onclick=()=>train(f);$('sell').onclick=()=>{show('<h2>Vender este pez</h2><p id="sellText"></p><div class="actions"><button id="confirmSell">Confirmar venta</button><button id="cancelSell">Conservar</button></div>');$('sellText').textContent=f.name+' se irá a un nuevo hogar. Recibirás '+sellValue(f)+' monedas.';$('cancelSell').onclick=()=>fishInfo(f);$('confirmSell').onclick=()=>{tank().fish=tank().fish.filter(x=>x.id!==f.id);state.coins+=sellValue(f);state.stats.sold=(state.stats.sold||0)+1;xp(10);$('dialog').close();save();render()}}}
function sellValue(f){return Math.floor(species(f.species).price*(.55+f.age/species(f.species).grow*.85+f.trained*.2))}
function breed(f){if(species(f.species).event)return toast('Este pez es único del evento.');const t=tank(),s=species(f.species);if(t.fish.length>=capacity())return toast('Necesitas espacio para la cría.');if(f.age<s.grow||f.hunger<60||f.cooldown>0||t.clean<60)return toast('Necesitas adultos alimentados, agua limpia y sin espera de cría.');const mate=t.fish.find(x=>x.id!==f.id&&x.species===f.species&&x.age>=s.grow&&x.hunger>=60&&x.cooldown<=0);if(!mate)return toast('Falta otro adulto de la misma especie que esté listo.');if(pay(Math.floor(s.price*.4))){f.cooldown=mate.cooldown=180;f.hunger-=15;mate.hunger-=15;t.fish.push(fish(s.id,'Bebé '+s.name));state.stats.bred++;xp(30);$('dialog').close();save();render();toast('💕 ¡Nació un nuevo '+s.name+'!')}}
function train(f){if(f.hunger<30)return toast('Alimenta a tu pez antes de entrenar.');if(f.trained>=7)return toast('Tu pez ya domina los siete trucos.');show('<h2>Escuela de burbujas</h2><p>Toca 8 burbujas en 15 segundos para aprender un truco.</p><p id="score"></p><div id="training"></div>');let hits=0,remaining=15;function target(){const b=document.createElement('button');b.className='target';b.textContent='🫧';b.style.left=(8+Math.random()*74)+'%';b.style.top=(5+Math.random()*65)+'%';b.onclick=()=>{hits++;if(hits>=8){clearInterval(trainingTimer);trainingTimer=null;f.trained++;f.hunger=Math.max(0,f.hunger-8);state.coins+=50;state.stats.trained++;xp(25);save();render();$('dialog').close();toast('¡Truco aprendido! +50 monedas');return}target();update()};$('training').replaceChildren(b)}function update(){$('score').textContent=hits+'/8 burbujas · '+remaining+' s'}target();update();trainingTimer=setInterval(()=>{remaining--;update();if(remaining<=0){clearInterval(trainingTimer);trainingTimer=null;$('dialog').close();toast('Se acabó el tiempo. ¡Puedes volver a intentarlo!')}},1000)}
$('settings').onclick=()=>{show('<h2>Tu pequeño océano</h2><p>Alimenta y limpia para que tus peces crezcan y produzcan monedas. Selecciona un pez para renombrar, criar, entrenar o vender. Compra decoraciones y colócalas en la arena. En Decorar puedes moverlas o guardarlas.</p><p>Como invitado, el progreso se guarda en este navegador. Con una cuenta, se guarda también en la nube. Al volver se simulan hasta 8 horas; los peces no mueren. Exporta para conservar una copia.</p><div class="actions"><button id="buyFood">50 comidas · 40 🪙</button><button id="theme">Cambiar paisaje</button></div><label>Nombre del acuario<input id="tankName" maxlength="28"></label><div class="actions"><button id="export">Exportar partida</button><button id="import">Importar partida</button></div><input id="file" type="file" accept="application/json" hidden>');$('tankName').value=tank().name;$('tankName').onchange=()=>{tank().name=$('tankName').value.trim()||'Mi arrecife';save();render()};$('buyFood').onclick=()=>buyFoodPack(FOOD_PACKS[1]);$('theme').onclick=()=>{tank().theme=(tank().theme+1)%3;save();toast('Un nuevo paisaje para tu acuario.')};$('export').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='acuario-feliz-partida.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const file=$('file').files[0];if(!file)return;if(file.size>1000000)throw Error();const incoming=normalizeSave(JSON.parse(await file.text()));if(!valid(incoming))throw Error();show('<h2>Importar partida</h2><p>Esta acción reemplazará el progreso actual. Puedes exportarlo antes de continuar.</p><div class="actions"><button id="confirmImport">Reemplazar partida</button><button id="cancelImport">Cancelar</button></div>');$('cancelImport').onclick=()=>$('dialog').close();$('confirmImport').onclick=()=>{setFeeding(false);particles=[];state=incoming;simulate((Date.now()-state.last)/1000);placing=null;editing=false;$('placement').style.display='none';$('dialog').close();save();render();toast('Partida importada')}}catch{toast('El archivo no es una partida válida.')}}};
const canvas=$('canvas'),ctx=canvas.getContext('2d');let W=900,H=560;function resize(){const r=canvas.getBoundingClientRect();W=r.width;H=r.height;canvas.width=Math.round(W*devicePixelRatio);canvas.height=Math.round(H*devicePixelRatio);ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}new ResizeObserver(resize).observe(canvas);
function decorBounds(d){const size=Math.min(W*.23,175)*decorScale(d);return{x:d.x*W-size/2,y:d.y*H-size,w:size,h:size}}
function drawDecoration(d,time){const s=deco(d.id),im=decorImage(s),r=decorBounds(d);ctx.save();ctx.translate(d.x*W,d.y*H);ctx.scale(d.flip?-1:1,1);if(s.id==='hw9')ctx.transform(1,0,Math.sin(time*.8)*.012,1,0,0);if(s.id==='hw3')ctx.transform(1,0,Math.sin(time)*.008,1,0,0);if(s.id==='coral')ctx.transform(1,0,Math.sin(time*1.2+d.x)*.018,1,0,0);if(s.id==='shell')ctx.scale(1,1+Math.sin(time*.8+d.x)*.025);if(im.complete&&im.naturalWidth)ctx.drawImage(im,-r.w/2,-r.h,r.w,r.h);ctx.restore();drawHalloweenFX(d,time,r);if(s.id==='volcano'){ctx.save();ctx.translate(d.x*W,d.y*H-r.h*.67);ctx.fillStyle='rgba(255,142,50,'+(.1+Math.sin(time*2)*.05)+')';ctx.beginPath();ctx.ellipse(0,0,r.w*.16,r.h*.04,0,0,7);ctx.fill();for(let i=0;i<7;i++){const lift=(time*22+i*17)%100;ctx.strokeStyle='rgba(225,255,255,'+(1-lift/110)+')';ctx.beginPath();ctx.arc(Math.sin(time+i)*8,-lift,2+i%3,0,7);ctx.stroke()}ctx.restore()}if(s.id==='ship'){ctx.strokeStyle='#daf9ff66';for(let i=0;i<3;i++){const lift=(time*13+i*30)%65;ctx.beginPath();ctx.arc(d.x*W+r.w*.2*(d.flip?-1:1),d.y*H-r.h*.5-lift,2,0,7);ctx.stroke()}}}
function draw(now){const dt=Math.min((now-lastFrame)/1000,.05);lastFrame=now;const t=tank(),time=now/1000;t.fish.forEach(f=>f.chasing=false);if(!gamePaused)updateFeeding(dt);bottle.pour=Math.max(0,bottle.pour-dt);const palettes=[['#7bcfd0','#238da1','#124c68'],['#bcabd9','#697db8','#35486d'],['#a2dcbd','#3f9e9b','#175e70']];const p=palettes[t.theme%3];let g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,p[0]);g.addColorStop(.48,p[1]);g.addColorStop(1,p[2]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);for(let i=0;i<7;i++){ctx.fillStyle='#dfffff0c';ctx.beginPath();ctx.moveTo(W*(i/6)-80,0);ctx.lineTo(W*(i/6)+70,0);ctx.lineTo(W*(i/6)+180,H);ctx.lineTo(W*(i/6)-20,H);ctx.fill()}for(let i=0;i<4;i++){ctx.fillStyle=i%2?'#175e6c30':'#13556940';ctx.beginPath();ctx.moveTo(0,H*.8);for(let x=0;x<=W+20;x+=20)ctx.lineTo(x,H*(.64+i*.045)+Math.sin(x/100+i*2)*H*.07);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill()}drawSubstrate();orderedDecor().forEach(d=>drawDecoration(d,time));for(let i=0;i<22;i++){const x=((i*97.3)%W)+Math.sin(time*.8+i)*8,y=H-((time*(12+i%4*5)+i*39)%H),r=2+i%4;ctx.strokeStyle='#d7ffff45';ctx.lineWidth=1;ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.stroke();ctx.fillStyle='#ffffff30';ctx.beginPath();ctx.arc(x-r*.3,y-r*.4,1,0,7);ctx.fill()}t.fish.forEach((f,i)=>{const s=species(f.species),scale=.55+.45*f.age/s.grow,size=Math.min(W*.15,115)*scale;if(!gamePaused&&!f.chasing){f.x+=f.dir*dt*(.017+(i%3)*.006);f.y+=(.38-f.y)*dt*.035;}if(!f.chasing){if(f.x>.9){f.x=.9;f.dir=-1}if(f.x<.09){f.x=.09;f.dir=1}}const y=f.y*H+Math.sin(time*.9+i*2)*H*(f.chasing?.003:.025);const im=fishImage(s);ctx.save();ctx.translate(f.x*W,y);ctx.scale(f.dir,1);ctx.rotate(Math.sin(time*3+i)*.025);drawSwimmingFish(im,size*(s.event?1.22:1),time*(s.event?1.3:1),i,f.chasing);if(s.event){ctx.fillStyle='#dbeeff';ctx.globalAlpha=.45+.3*Math.sin(time*4);ctx.beginPath();ctx.arc(size*.33,-size*.03,1.6,0,7);ctx.fill()} ctx.restore();if(f.hunger<25){ctx.font='16px sans-serif';ctx.fillText('🌾',f.x*W-8,y-size*.5)}if(f.bite>0){f.bite-=dt;ctx.font='16px sans-serif';ctx.fillStyle='#fff0a0';ctx.fillText('✦',f.x*W,y-size*.45)}f.hit={x:f.x*W,y,r:size*.48}});if(t.clean<70){ctx.fillStyle=`rgba(87,112,48,${(70-t.clean)/180})`;ctx.fillRect(0,0,W,H)}particles.filter(q=>q.tank===state.active).forEach(q=>{ctx.fillStyle=q.type==='food'?'#ffd985':'#fff6b3';ctx.beginPath();ctx.arc(q.x*W,q.y*H,q.type==='food'?3:5*q.life,0,7);ctx.fill();if(q.type==='food'){ctx.strokeStyle='#b08039';ctx.stroke()}});if(feeding&&bottle.visible){ctx.save();ctx.translate(bottle.x*W,bottle.y*H);ctx.rotate(bottle.pour>0?-.65:-.25);ctx.fillStyle='#d5f1d9';ctx.strokeStyle='#397a70';ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(6,-56,32,45,7);ctx.fill();ctx.stroke();ctx.fillStyle='#d89e52';ctx.fillRect(9,-33,26,19);ctx.fillStyle='#fff4d1';ctx.fillRect(9,-48,26,15);ctx.fillStyle='#388477';ctx.fillRect(12,-66,20,11);ctx.font='10px sans-serif';ctx.fillStyle='#467268';ctx.fillText('🐟',14,-36);ctx.restore();} if(editing){ctx.setLineDash([4,4]);ctx.strokeStyle='#fff9';t.decor.forEach(d=>{const r=decorBounds(d);ctx.strokeStyle=d.uid===decorSelected?'#fff2a8':'#ffffff66';ctx.lineWidth=d.uid===decorSelected?3:1;ctx.strokeRect(r.x,r.y,r.w,r.h)});ctx.setLineDash([])}requestAnimationFrame(draw)}
let drag=null;function coords(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/W,y:(e.clientY-r.top)/H}}
canvas.addEventListener('pointerdown',e=>{const q=coords(e);if(feeding){bottle={...bottle,...q,visible:true};dropFood(q);return}if(placing){const i=state.inventory.findIndex(x=>x.uid===placing.uid);if(i<0)return;const item=state.inventory.splice(i,1)[0];tank().decor.push({uid:item.uid,id:item.id,scale:decorScale(item),flip:!!item.flip,layer:nextDecorLayer(),x:Math.max(.05,Math.min(.95,q.x)),y:Math.max(.77,Math.min(.96,q.y))});state.stats.decorated++;xp(6);placing=null;$('placement').style.display='none';save();render();return}if(editing){const d=orderedDecor().reverse().find(d=>(()=>{const r=decorBounds(d);return q.x*W>=r.x&&q.x*W<=r.x+r.w&&q.y*H>=r.y&&q.y*H<=r.y+r.h})());if(d){decorSelected=d.uid;renderDecorEditor();drag={d,start:q,moved:false,origin:{x:d.x,y:d.y}};canvas.setPointerCapture(e.pointerId)}return}const f=tank().fish.slice().reverse().find(f=>f.hit&&Math.hypot(f.hit.x-q.x*W,f.hit.y-q.y*H)<f.hit.r);if(f)fishInfo(f)});
canvas.addEventListener('pointermove',e=>{const q=coords(e);if(feeding)bottle={...bottle,...q,visible:true};if(!drag)return;if(Math.hypot(q.x-drag.start.x,q.y-drag.start.y)>.01)drag.moved=true;if(drag.moved){drag.d.x=Math.max(.05,Math.min(.95,drag.origin.x+q.x-drag.start.x));drag.d.y=Math.max(.5,Math.min(.96,drag.origin.y+q.y-drag.start.y))}});
canvas.addEventListener('pointerleave',()=>{bottle.visible=false});
canvas.addEventListener('pointerup',()=>{if(!drag)return;drag=null;save();renderDecorEditor()});canvas.addEventListener('pointercancel',()=>{drag=null;save()});
setInterval(()=>{simulate(1);$('clean').textContent=Math.round(tank().clean);$('income').textContent=Math.floor(tank().bank)+' disponibles'},1000);setInterval(save,10000);window.addEventListener('pagehide',save);render();save();requestAnimationFrame(draw);



window.aquariumGame.reserve=()=> (state.expeditionFish||[]).filter(r=>['fang','royal'].includes(r.species)).map(r=>({...r,name:species(r.species).name,src:FISH_ASSETS[r.species].src}));
window.aquariumGame.receiveFish=(id,index)=>{if(gamePaused||!Number.isInteger(index)||!state.tanks[index])return false;const t=state.tanks[index],i=(state.expeditionFish||[]).findIndex(r=>r.id===id&&['fang','royal'].includes(r.species));if(i<0)return false;if(t.fish.length>=8+t.size*4){toast('Ese acuario está lleno. Tu pez sigue seguro en la reserva.');return false}const r=state.expeditionFish.splice(i,1)[0];t.fish.push(fish(r.species));save();render();toast('¡Tu pez de expedición llegó al acuario!');return true};
// Vista independiente: jamás sustituye la partida propia ni ejecuta sus controles.
window.aquariumGame.drawVisit=(surface,incoming,time)=>{
 const c=surface.getContext('2d'),w=surface.width,h=surface.height;
 const number=(x,d=0)=>Number.isFinite(Number(x))?Number(x):d;
 const clamp=(x,a,b,d=a)=>Math.max(a,Math.min(b,number(x,d)));
 const palettes=[['#7bcfd0','#124c68'],['#bcabd9','#35486d'],['#a2dcbd','#175e70']];
 const p=palettes[Math.floor(clamp(incoming.theme,0,2))],g=c.createLinearGradient(0,0,0,h);g.addColorStop(0,p[0]);g.addColorStop(1,p[1]);c.fillStyle=g;c.fillRect(0,0,w,h);
 for(let i=0;i<6;i++){c.fillStyle='#dfffff0c';c.beginPath();c.moveTo(w*i/5-50,0);c.lineTo(w*i/5+50,0);c.lineTo(w*i/5+100,h);c.lineTo(w*i/5-20,h);c.fill()}
 const sub=SUBSTRATES.find(s=>s.id===incoming.substrate)||SUBSTRATES[0];c.fillStyle=sub.colors[0];c.fillRect(0,h*.87,w,h*.13);
 for(let i=0;i<900;i++){c.fillStyle=sub.colors[i%sub.colors.length];c.beginPath();c.ellipse((i*137.1)%w,h*.875+((i*71.3)%(h*.125)),sub.sand?1:3+i%3,sub.sand?1:2+i%2,0,0,7);c.fill()}
 (Array.isArray(incoming.decor)?incoming.decor:[]).slice(0,100).filter(d=>deco(d.id)).sort((a,b)=>number(a.layer)-number(b.layer)).forEach(d=>{const s=deco(d.id),im=decorImage(s),size=Math.min(w*.23,175)*clamp(d.scale,.4,2,1);c.save();c.translate(clamp(d.x,0,1)*w,clamp(d.y,0,1)*h);c.scale(d.flip?-1:1,1);if(['coral','hw3','hw9'].includes(s.id))c.transform(1,0,Math.sin(time)*.018,1,0,0);if(im.complete&&im.naturalWidth)c.drawImage(im,-size/2,-size,size,size);if(['volcano','hw4'].includes(s.id)){c.strokeStyle=s.id==='hw4'?'#c3ff99':'#deffff';for(let j=0;j<5;j++){c.beginPath();c.arc(Math.sin(time+j)*8,-size*.7-(time*20+j*16)%90,2+j%3,0,7);c.stroke()}}c.restore()});
 (Array.isArray(incoming.fish)?incoming.fish:[]).slice(0,40).filter(f=>species(f.species)).forEach((f,i)=>{const s=species(f.species),im=fishImage(s),size=Math.min(w*.15,115)*(.55+.45*clamp(number(f.age)/s.grow,0,1)),x=(clamp(f.x,.1,.9)*w+Math.sin(time*.2+i)*w*.04),y=clamp(f.y,.12,.75)*h+Math.sin(time+i)*h*.02;c.save();c.translate(x,y);c.scale(f.dir===-1?-1:1,1);if(im.complete&&im.naturalWidth){const ih=size*im.naturalHeight/im.naturalWidth;for(let n=0;n<32;n++){const u=n/32;c.drawImage(im,n*im.naturalWidth/32,0,im.naturalWidth/32,im.naturalHeight,-size/2+n*size/32,-ih/2+Math.sin(time*6+u*3.5+i)*size*.035*(1-u)**2,size/32+.4,ih)}}c.restore()});
 for(let i=0;i<15;i++){c.strokeStyle='#d7ffff60';c.beginPath();c.arc((i*97.3)%w,h-(time*(12+i%4*5)+i*39)%h,2+i%4,0,7);c.stroke()}
};
